+
+func parseWhyLineRange(raw string) (whyLineRange, error) {
+	raw = strings.TrimSpace(raw)
+	if raw == "" {
+		return whyLineRange{}, nil
+	}
+
+	parseLine := func(value string) (int, error) {
+		n, err := strconv.Atoi(value)
+		if err != nil || n <= 0 {
+			return 0, fmt.Errorf("invalid line range %q", raw)
+		}
+		return n, nil
+	}
+
+	if strings.Contains(raw, "-") {
+		parts := strings.Split(raw, "-")
+		if len(parts) != 2 {
+			return whyLineRange{}, fmt.Errorf("invalid line range %q", raw)
+		}
+		start, err := parseLine(parts[0])
+		if err != nil {
+			return whyLineRange{}, err
+		}
+		end, err := parseLine(parts[1])
+		if err != nil {
+			return whyLineRange{}, err
+		}
+		if start > end {
+			return whyLineRange{}, fmt.Errorf("invalid line range %q: start must be <= end", raw)
+		}
+		return whyLineRange{Start: start, End: end}, nil
+	}
+
+	line, err := parseLine(raw)
+	if err != nil {
+		return whyLineRange{}, err
+	}
+	return whyLineRange{Start: line, End: line}, nil
+}
+
+func (r whyLineRange) gitRange() string {
+	if r.Start == 0 && r.End == 0 {
+		return ""
+	}
+	return fmt.Sprintf("%d,%d", r.Start, r.End)
+}
+
+func resolveWhyPath(ctx context.Context, input string) (string, string, string, error) {
+	repoRoot, err := paths.WorktreeRoot(ctx)
+	if err != nil {
+		return "", "", "", fmt.Errorf("not a git repository: %w", err)
+	}
+
+	absPath := input
+	if !filepath.IsAbs(absPath) {
+		absPath, err = filepath.Abs(absPath)
+		if err != nil {
+			return "", "", "", fmt.Errorf("resolving path %q: %w", input, err)
+		}
+	}
+	absPath = filepath.Clean(absPath)
+
+	relPath, err := filepath.Rel(repoRoot, absPath)
+	if err != nil {
+		return "", "", "", fmt.Errorf("resolving path %q relative to repository: %w", input, err)
+	}
+	if relPath == "." || strings.HasPrefix(relPath, ".."+string(filepath.Separator)) || relPath == ".." {
+		return "", "", "", fmt.Errorf("path %q is outside the repository", input)
+	}
+
+	return repoRoot, filepath.ToSlash(relPath), absPath, nil
+}
+
+func whyPathExistsAtHEAD(_ context.Context, repoRoot, gitPath string) error {
+	repo, err := git.PlainOpen(repoRoot)
+	if err != nil {
+		return fmt.Errorf("opening repository: %w", err)
+	}
+	head, err := repo.Head()
+	if err != nil {
+		return fmt.Errorf("resolving HEAD: %w", err)
+	}
+	commit, err := repo.CommitObject(head.Hash())
+	if err != nil {
+		return fmt.Errorf("reading HEAD commit: %w", err)
+	}
+	tree, err := commit.Tree()
+	if err != nil {
+		return fmt.Errorf("reading HEAD tree: %w", err)
+	}
+	if _, err := tree.File(gitPath); err != nil {
+		return fmt.Errorf("path %q does not exist as a file at HEAD: %w", gitPath, err)
+	}
+	return nil
+}
