+func traceStepNameWidth(steps []traceStep) int {
+	nameWidth := len("STEP")
+	for _, step := range steps {
+		if len(step.Name) > nameWidth {
+			nameWidth = len(step.Name)
+		}
+		nameWidth = traceSubStepNameWidth(nameWidth, step.SubSteps, 0)
+	}
+	return nameWidth
+}
+
+func traceSubStepNameWidth(nameWidth int, steps []traceStep, level int) int {
+	for _, step := range steps {
+		if needed := len(step.Name) + traceSubStepExtraIndent(level); needed > nameWidth {
+			nameWidth = needed
+		}
+		nameWidth = traceSubStepNameWidth(nameWidth, step.SubSteps, level+1)
+	}
+	return nameWidth
+}
+
+func traceSubStepExtraIndent(level int) int {
+	return 5 + 4*level
+}
+
+func renderTraceSubSteps(w io.Writer, steps []traceStep, nameWidth, level int) {
+	for i, sub := range steps {
+		connector := "├─"
+		if i == len(steps)-1 {
+			connector = "└─"
+		}
+		subDur := fmt.Sprintf("%dms", sub.DurationMs)
+		pad := nameWidth - traceSubStepExtraIndent(level) - len(sub.Name)
+		if pad < 0 {
+			pad = 0
+		}
+		indent := strings.Repeat("    ", level+1)
+		subLine := fmt.Sprintf("%s%s %s%s  %8s", indent, connector, sub.Name, strings.Repeat(" ", pad), subDur)
+		if sub.Error {
+			subLine += "  x"
+		}
+		fmt.Fprintln(w, subLine)
+		renderTraceSubSteps(w, sub.SubSteps, nameWidth, level+1)
+	}
+}
