+// ResolveCommittedMetadataAndPromptsForCheckpoint resolves checkpoint summary and
+// latest-session metadata/prompts with v2-first, v1-fallback behavior.
+func ResolveCommittedMetadataAndPromptsForCheckpoint(
+	ctx context.Context,
+	checkpointID id.CheckpointID,
+	v1Store *GitStore,
+	v2Store *V2GitStore,
+	preferCheckpointsV2 bool,
+) (*CheckpointSummary, *SessionContent, error) {
+	if err := ctx.Err(); err != nil {
+		return nil, nil, err //nolint:wrapcheck // Propagating context cancellation
+	}
+
+	if preferCheckpointsV2 && v2Store != nil {
+		summary, content, err := readCommittedMetadataAndPrompts(ctx, v2Store, checkpointID)
+		if err == nil && summary != nil {
+			return summary, content, nil
+		}
+		if err != nil && ctx.Err() != nil {
+			return nil, nil, ctx.Err() //nolint:wrapcheck // Propagating context cancellation
+		}
+		if err != nil && !errors.Is(err, ErrCheckpointNotFound) && !errors.Is(err, ErrNoTranscript) {
+			logging.Debug(ctx, "v2 metadata read failed, falling back to v1",
+				slog.String("checkpoint_id", checkpointID.String()),
+				slog.String("error", err.Error()),
+			)
+		}
+	}
+
+	if v1Store == nil {
+		return nil, nil, ErrCheckpointNotFound
+	}
+
+	summary, content, err := readCommittedMetadataAndPrompts(ctx, v1Store, checkpointID)
+	if err != nil {
+		return nil, nil, err
+	}
+	if summary == nil {
+		return nil, nil, ErrCheckpointNotFound
+	}
+	return summary, content, nil
+}
+
+func readCommittedMetadataAndPrompts(ctx context.Context, reader committedMetadataAndPromptsReader, checkpointID id.CheckpointID) (*CheckpointSummary, *SessionContent, error) {
+	summary, content, err := reader.ReadCommittedLatestSessionMetadataAndPrompts(ctx, checkpointID)
+	if err != nil {
+		return nil, nil, err
+	}
+	return summary, content, nil
+}
+
